"""57-line review register; preserves phase17 statuses without anatomical promotion."""
import csv,json
from pathlib import Path
D=Path('docs/coach/phase18');P=Path('docs/coach/phase17')
ORIGINAL={'AH':'Anterior Head','PH':'Posterior Head','SJN':'Sternum Jugular Notch','SXS':'Sternum Xiphoid Process','CV7':'Cervical Spine Vertebra 7','TV2':'Thoracic Spine Vertebra 2','TV7':'Thoracic Spine Vertebra 7','HGT':'Glenohumeral Joint','IAS':'Iliac Anterior Spine; PSIS alias','IPS':'Iliac Posterior Spine; ASIS alias','CAJ':'Clavicle-Acromion Joint','HLE':'Humerus Lateral Epicondyle','HME':'Humerus Medial Epicondyle','UA':'Upper Arm','HM2':'Hand Second metatarsal','USP':'Ulna Styloid Process','RSP':'Radius Styloid Process','FTC':'Femoral greater Trochanter','FLE':'Femur Lateral Epicondyle','FME':'Femur Medial Epicondyle','TH':'Thigh','SK':'Superior Knee; Upper Leg','TTC':'Tibial Tubercle','FAX':'Fibula Apex','FAL':'Fibula Ankle Lateral','TAM':'Talus Ankle Medial','FM1':'Foot First Metatarsal','FM2':'Foot Second Metatarsal','FM5':'Foot Fifth Metatarsal','FCC':'Foot Calcaneus','DP1':'First Distal Phalanx'}
SPECIAL={
'IAS':('Texte antérieur ou alias PSIS postérieur ; aucune permutation proposée','Orientation du bassin, repère local et estimation de hanche erronés','P1','Quelle définition antérieure/postérieure a réellement été palpée sur AB01 et quelle preuve permet d’écarter l’alias contradictoire ?'),
'IPS':('Texte postérieur ou alias ASIS antérieur ; aucune permutation proposée','Orientation du bassin et résultats de scaling torso/pelvis biaisés','P1','Pouvez-vous établir le site postérieur réel et les signes du repère pelvien, indépendamment de la seule position apparente ?'),
'TV2':('T2 nominal versus trois niveaux sous C7','Orientation du thorax et registration incohérentes','P2','Quel niveau vertébral est visé et existe-t-il une preuve du placement AB01 ?'),
'HM2':('Métacarpien sous l’index probable versus mot metatarsal imprimé','Dimension de main, poignet et marqueur virtuel mal interprétés','P1','Confirmez-vous le site sur le deuxième métacarpien, l’offset asymétrique éventuel et sa preuve individuelle ?'),
'USP':('Styloïde ulnaire nominale ; placement lateral et parent radius à examiner','Rotation/pronation de l’avant-bras et axe du poignet biaisés','P1','Quel côté du poignet et quelle posture définissent le placement ? Le rattachement à radius est-il acceptable pendant ce geste ?'),
'RSP':('Styloïde radiale nominale versus indication medial','Inversion des marqueurs du poignet et orientation de main erronée','P1','Comment résoudre medial/lateral sans inverser les labels ? Quelle posture de référence et quelle preuve ?'),
'SK':('Site sur tibia décrit versus Superior Knee/Upper Leg','Affectation de segment incorrecte et erreur liée aux tissus mous','P2','Le marqueur est-il bien sur la jambe ? Quelle incertitude de placement et de rigidité accepter ?'),
'FTC':('Landmark fémoral mais rattachement pelvis documenté','Mouvement relatif hanche/fémur absorbé dans le bassin et scaling','P1','L’hypothèse FTC solidaire du pelvis est-elle défendable en flexion profonde ? Quel contrôle la contredirait ?'),
'HGT':('Landmark superficiel postérieur d’épaule, pas centre profond','Confusion entre peau, ceinture scapulaire et centre glénohuméral','P1','Quelle mobilité relative au torso faut-il considérer et quel modèle de centre articulaire serait requis ?'),
'DP1':('Landmark distal d’orteil mais parent calcn et MTP verrouillée','Contact avant-pied et flexion des orteils mal représentés','P1','L’approximation rigide calcn–orteil est-elle acceptable pour une analyse des appuis, et pour quelles conclusions seulement ?'),
'FLE':('Épicondyle cutané versus centre virtuel de genou','Axe et flexion du genou biaisés','P1','Quelle méthode de centre/axe de genou est justifiée avec le marqueur médial statique retiré en dynamique ?'),
'FME':('Calibration médiale, pas centre articulaire observé','Estimation de genou non reproductible après retrait','P1','Quelle calibration et quelle propagation à la dynamique permettent d’utiliser ce landmark sans assimiler sa position au centre ?'),
'FAL':('Malléole latérale, pas centre de cheville','Orientation de cheville et appui biaisés','P1','Quelle calibration médiale/latérale et quel axe individualisé seraient nécessaires ?'),
'TAM':('Malléole médiale décrite, titre Talus Ankle Medial','Confusion osseuse et centre de cheville incorrect','P1','Peut-on confirmer le landmark tibial palpable malgré le titre, et son rôle de calibration uniquement ?')}
def main():
 rows=list(csv.DictReader((P/'marker-anatomical-mapping.csv').read_text().splitlines()));out=[]
 for i,r in enumerate(rows,1):
  name=r['original_name'];key=name if name in ORIGINAL else name[1:];interpret,consequence,priority,question=SPECIAL.get(key,('Landmark superficiel documenté ; placement individuel et rigidité non démontrés','Orientation, échelle ou suivi du segment biaisés par erreur de placement ou tissus mous','P2','Le site palpé, la latéralité et la fixation au segment sont-ils suffisamment documentés pour AB01 ? Quelle incertitude et quelle vérification exigez-vous ?'))
  out.append({'id':f'M{i:02}','marker':name,'original_term':ORIGINAL[key],'phase17_definition':r['documented_anatomical_location'],'phase17_status':r['anatomical_status'],'contradiction_or_limit':r['justification'],'possible_interpretations':interpret,'consequence':consequence,'priority':priority,'expert_question':question,'side':r['side'],'opensim_parent':r['opensim_parent_frame'],'joint_centre_status':'Inconnu','rocketbox_status':'Inconnu','source':r['source_documentation']+' ; '+r['source_xml'],'expert_answer':None})
 (D/'marker-review-register.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
 with (D/'marker-review-register.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(out[0]),lineterminator='\n');w.writeheader();w.writerows(out)
 md='# Incertitudes anatomiques — registre contradictoire\n\n**44 définitions documentaires confirmées et 13 plausibles, sans promotion.** Aucun centre articulaire ni mapping Rocketbox confirmé. «Confirmé» décrit une proposition documentaire, pas le placement sur AB01 ni une validation professionnelle. Chaque marqueur nécessite une réponse ; P1 signale les priorités anatomiques, P2 le contrôle obligatoire restant.\n\nLes termes anglais ci-dessous reprennent le libellé anatomique de la documentation OptiTrack, sans préfixe Left/Right : le côté est conservé dans le CSV. Les définitions françaises viennent de phase17. Le texte contradictoire n’est pas corrigé silencieusement. Source : [OptiTrack Biomech57](https://docs.optitrack.com/movement-sciences/movement-sciences-markersets/biomech-57), sections par région ; [CSV original de phase17](../phase17/marker-anatomical-mapping.csv).\n\n## Questions transversales obligatoires\n\n- **Bassin et centres :** quelle orientation signée et quelle méthode d’estimation individualisée sont défendables ? Un milieu de marqueurs ou la description du squelette Motive n’est pas automatiquement une articulation OpenSim.\n- **Gauche/droite :** les noms documentent la latéralité attendue, pas l’absence de permutation pendant le labelling. Quelle preuve relie labels, palpation et pied/plateforme pour toute la prise ? Aucune inversion automatique.\n- **Tissus mous :** vêtements, peau et marqueurs peuvent se déplacer relativement aux os. Quel budget d’incertitude par région et quelles limites aux degrés de liberté observables ? L’absence de trous après interpolation ne résout pas ce problème.\n- **Scaling/registration :** 46 champs fixed=false et 11 champs absents ; quelle version de défaut, quel déplacement de marqueur et quelles contraintes étaient effectivement utilisés ?\n- **Rocketbox :** les pivots, proportions, axes de repos et degrés de liberté du rig ne sont pas des centres anatomiques certifiés. Aucun des 57 points ne reçoit ici une correspondance de transfert.\n\n## Registre des 57 marqueurs\n\n[CSV exploitable](marker-review-register.csv) · [JSON avec réponses nulles](marker-review-register.json) · [Schéma documentaire](../phase17/markerset-schematic.svg) · [Points statiques mesurés](../phase17/static-marker-projections.svg)\n'
 for r in out:
  md+=f"\n### {r['id']} — {r['marker']} · {r['phase17_status']} · {r['priority']}\n\n**Définition originale :** {r['original_term']}. {r['phase17_definition']} ({r['side']}).\n\n**Contradiction ou limite :** {r['contradiction_or_limit']} Parent logiciel : `{r['opensim_parent']}`.\n\n**Interprétations possibles :** {r['possible_interpretations']}.\n\n**Conséquence d’une erreur :** {r['consequence']}.\n\n**Question à l’expert :** {r['expert_question']}\n\nSource : {r['source']}.\n"
 (D/'anatomical-uncertainties.md').write_text(md)
if __name__=='__main__':main()
